css:
:scope { width: min(100%, 1407px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 10 / span 14; grid-row: 1 / span 81; aspect-ratio: 821 / 648; }
.gx__i2 { grid-column: 1 / span 9; grid-row: 3 / span 9; font-family: var(--os-font-label); font-size: 52px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; text-align: center; color: var(--os-color-text); }
